/ ==== leaf:issueDetailFold (spliced by build) ==== // ==== leaf:useIssueDetailFold (spliced by build) ==== // ==== leaf:IssueDetail (spliced by build) ====\n\n    // ==== leaf:tagsFit (spliced by build) ====\n    // ==== leaf:pop (spliced by build) ====\n    // ==== leaf:noRepoCard (spliced by build) ====\n    // ==== leaf:setupCard (spliced by build) ====\n    // ==== leaf:ListTabClosed (spliced by build) ==== // ==== leaf:ListTabRow (spliced by build) ==== // ==== leaf:listFilterRow (spliced by build) ==== // ==== leaf:mdEffortRow (spliced by build) ==== // ==== leaf:listTab (spliced by build) ====\n\n    // ==== leaf:prTab (spliced by build) ====\n\n\n    // ==== leaf:skillsTab (spliced by build) ====\n    // 887：技能详情像素风中组件与整页（皮肤拼在上面样式区）。\n    // ==== leaf:pixelContents (spliced by build) ====\n    // ==== leaf:pixelMarkdown (spliced by build) ====\n    // ==== leaf:pixelSkillRow (spliced by build) ====\n    // ==== leaf:pixelSkillList (spliced by build) ====\n    // ==== leaf:pixelSkillDetailModal (spliced by build) ====\n    // ==== leaf:pixelSkillOps (spliced by build) ====\n\n    // ==== leaf:checksTab (spliced by build) ====\n\n    const TABS_FOLD_HYST = 4\n    const TABS_LEVELS = 3\n    const tabsLevelDecide = function (level: any, avail: any, nats: any) {\n      if (!Array.isArray(nats) || !nats.length) return 0\n      let cur = level < 0 ? 0 : level\n      while (cur < nats.length - 1 && nats[cur] > avail + 1) cur++\n      while (cur > 0 && avail >= nats[cur - 1] + TABS_FOLD_HYST) cur--\n      return cur\n    }\n    // issue#15 修复：scrollWidth 会被容器宽度钳制（容器宽于内容时 scrollWidth===clientWidth），\n    // 导致折叠后展开判定 avail>=nats[cur-1]+4 永不成立（死锁）。改测内容 children 的真实横跨宽。\n    const measureContentWidth = function (t: any) {\n      if (!t || !t.children || t.children.length === 0) return 0\n      const tr = t.getBoundingClientRect()\n      let minX = Infinity, maxX = -Infinity\n      for (let i = 0; i < t.children.length; i++) {\n        const c = t.children[i]\n        const r = c.getBoundingClientRect()\n        if (r.width > 0) { if (r.x < minX) minX = r.x; if (r.x + r.width > maxX) maxX = r.x + r.width }\n      }\n      if (minX === Infinity) return 0\n      return maxX - tr.x\n    }\n    // ==== leaf:namingFailBanner (spliced by build) ====\n\n    // 2026-09-24：快照还没回来时那条灰色占位骨架（排在 dock 之前 —— 面板头部那一行要画它）。\n    // ==== leaf:repoChipSkeleton (spliced by build) ====\n    // #1833：头部刷新按钮旁那枚「当前是不是失败」的小标识（判据在 truthLines，排在 dock 之前拼进闭包）。\n    // ==== leaf:refreshFailMark (spliced by build) ====\n    // ==== leaf:DockSync (spliced by build) ==== // ==== leaf:headFold (spliced by build) ==== // ==== leaf:notificationCenterModel (spliced by build) ==== // ==== leaf:notificationCenter (spliced by build) ==== // ==== leaf:dock (spliced by build) ====\n\n    // ==== leaf:OverlayGate (spliced by build) ====\n\n    // ==== kernel:updateClient (spliced by build) ====\n\n    // ==== kernel:updateEntryBundle (spliced by build) ====\n\n    // ==== leaf:diagnosticLogModel (spliced by build) ==== // ==== leaf:diagnosticLogActions (spliced by build) ==== // ==== leaf:diagnosticLogSection (spliced by build) ==== // ==== leaf:SettingsWorkspaces (spliced by build) ====\n    // #876：更新入口挂载点（只挂包的入口件，含内部 dialog 面板；本仓不再自带按钮状态机与浮层弹窗）\n    // ==== leaf:updateEntryHost (spliced by build) ==== // ==== leaf:settingsPage (spliced by build) ====\n    // ==== leaf:runPanel (spliced by build) ==== // ==== leaf:panelAssembly (spliced by build) ====\n  },\n}"
